import { chromium } from 'playwright';
import fs from 'node:fs';

const OUT='/tmp/chapter2-pass3-final';
fs.mkdirSync(OUT,{recursive:true});
const results={checks:[],errors:[],screenshots:[]};
function assert(cond,msg){if(!cond)throw new Error(msg)}
function check(name,detail='ok'){results.checks.push({name,detail});console.log('CHECK',name,detail)}
async function shot(page,name){await page.screenshot({path:`${OUT}/${name}.png`,fullPage:false});results.screenshots.push(name+'.png')}
const browser=await chromium.launch({headless:true});
async function makeContext(unlocked=400){const ctx=await browser.newContext({viewport:{width:390,height:844},deviceScaleFactor:1});const stars={};for(let i=1;i<unlocked;i++)stars[i]=3;await ctx.addInitScript(({unlocked,stars})=>{localStorage.setItem('latchlings_campaign400_progress_v1',JSON.stringify({unlocked,stars}));localStorage.setItem('latchlings_cinematics_seen_v1',JSON.stringify({opening:1,'across-drift':1,'old-maps':1,homeward:1}));localStorage.setItem('latchlings_ui_prefs_v1',JSON.stringify({motion:'system',textSize:'normal'}))},{unlocked,stars});return ctx}
async function settleTransition(page){await page.evaluate(async()=>{try{const t=eval('activeScreenTransition');if(t?.finished)await t.finished}catch(_){}});await page.waitForTimeout(90)}

// Clean movement-3 Atlas view.
const ac=await makeContext(400),ap=await ac.newPage();ap.setDefaultTimeout(10000);ap.on('pageerror',e=>results.errors.push('atlas: '+String(e)));await ap.goto('http://127.0.0.1:4173/',{waitUntil:'networkidle'});await ap.evaluate(()=>eval("chapterView=2;rangeView=2;screen('levels');renderChapter()"));await settleTransition(ap);const atlas=await ap.evaluate(()=>{const map=document.getElementById('levelGrid'),e=map.querySelector('.atlas-scene em'),a=getComputedStyle(e,'::after'),r=e.getBoundingClientRect();return{screen:document.body.dataset.screen,range:map.className,w:r.width,h:r.height,lights:a.boxShadow,story:document.getElementById('storyCardOverlay')?.classList.contains('show'),modal:document.getElementById('overlay')?.classList.contains('show')}});assert(atlas.screen==='levels'&&/atlas-range-3/.test(atlas.range)&&atlas.w>35&&atlas.h>25&&atlas.lights!=='none'&&!atlas.story&&!atlas.modal,'Atlas landmark evidence invalid: '+JSON.stringify(atlas));check('Clean Atlas twin-lantern porch',JSON.stringify(atlas));await shot(ap,'chapter2-atlas-twin-lantern-porch-final-390');await ac.close();

// Clean Little Home stage-2 pennant. It must be spatially separate from the cottage so the payoff reads as a flag, not a glowing door.
const hc=await makeContext(101),hp=await hc.newPage();hp.setDefaultTimeout(10000);hp.on('pageerror',e=>results.errors.push('home: '+String(e)));await hp.goto('http://127.0.0.1:4173/',{waitUntil:'networkidle'});await hp.evaluate(()=>window.focusHomeReward('pennant'));await hp.waitForTimeout(180);const frame=hp.frameLocator('#homeTitleFrame');await frame.locator('#c2 .story-pennant').waitFor({state:'visible'});const home=await frame.locator('#c2 .phone').evaluate(phone=>{const p=phone.querySelector('.story-pennant'),c=phone.querySelector('.cottage'),pr=p.getBoundingClientRect(),cr=c.getBoundingClientRect(),after=getComputedStyle(p,'::after');const overlap=pr.left<cr.right&&pr.right>cr.left&&pr.top<cr.bottom&&pr.bottom>cr.top;return{stage2:phone.classList.contains('story-stage-2'),focus:phone.classList.contains('story-focus-pennant'),pennant:{left:pr.left,top:pr.top,right:pr.right,bottom:pr.bottom,display:getComputedStyle(p).display,flagBg:after.backgroundImage||after.backgroundColor,flagW:after.width,flagH:after.height},cottage:{left:cr.left,top:cr.top,right:cr.right,bottom:cr.bottom},overlap}});assert(home.stage2&&home.focus&&home.pennant.display!=='none','Pennant state missing: '+JSON.stringify(home));assert(!home.overlap,'Pennant still overlaps cottage: '+JSON.stringify(home));assert(parseFloat(home.pennant.flagW)>=24&&parseFloat(home.pennant.flagH)>=13,'Pennant flag is not visually substantial: '+JSON.stringify(home));const outer=await hp.evaluate(()=>({screen:document.body.dataset.screen,transition:!!document.querySelector('.screen-transition-outgoing')}));assert(outer.screen==='home'&&!outer.transition,'Home evidence caught transition: '+JSON.stringify(outer));check('Readable Little Home visitor pennant',JSON.stringify(home));await shot(hp,'chapter2-home-pennant-focus-final-390');await hc.close();

assert(results.errors.length===0,'Browser errors: '+JSON.stringify(results.errors));fs.writeFileSync(`${OUT}/results.json`,JSON.stringify(results,null,2));console.log('CHAPTER2_PASS3_FINAL_EVIDENCE_ACCEPTED');await browser.close();
